INSERT INTO categories (id, webflow_item_id, name, tagline, short_description, color_key, sort_order) VALUES ('everyday-spending', '6a8578266d00107b3bf3f481', 'Everyday Spending', 'Groceries, brands, leaving Amazon', 'Groceries, household goods, and retail — learn who actually owns the brands in your basket, then redirect that spending one aisle at a time.', 'c1', 1);
INSERT INTO categories (id, webflow_item_id, name, tagline, short_description, color_key, sort_order) VALUES ('subscriptions', '6a8578266d00107b3bf3f483', 'Subscriptions', 'What''s quietly billing you monthly', 'Recurring digital revenue is what moves valuations. Audit every subscription you pay, cancel what you can, and move the rest to providers outside the target set.', 'c2', 2);
INSERT INTO categories (id, webflow_item_id, name, tagline, short_description, color_key, sort_order) VALUES ('money-banking', '6a8578266d00107b3bf3f485', 'Money & Banking', 'Where your money sleeps at night', 'Your deposits are working capital that your bank lends and invests. Move them to member-owned institutions and pay on rails that don''t route a fee to a US network.', 'c3', 3);
INSERT INTO categories (id, webflow_item_id, name, tagline, short_description, color_key, sort_order) VALUES ('investments', '6a8578266d00107b3bf3f487', 'Investments', 'You may own what you''re boycotting', 'You are probably already funding what you''re boycotting. Find out what your pension holds, then decide whether to move it, vote it, or organise around it.', 'c1', 4);
INSERT INTO categories (id, webflow_item_id, name, tagline, short_description, color_key, sort_order) VALUES ('travel', '6a85786ec61c6c719566ef1c', 'Travel', 'The one with a public scoreboard', 'The only category with a public scoreboard — inbound tourism and vehicle registrations are published monthly. Skip the trip, skip the brand, and say why.', 'c2', 5);
INSERT INTO categories (id, webflow_item_id, name, tagline, short_description, color_key, sort_order) VALUES ('institutions', '6a85786ec61c6c719566ef1e', 'Institutions', 'Highest impact, most effort', 'One organisation switching outweighs a thousand individual consumers. Your employer, council, union, club and congregation all sign contracts — and someone has to raise it.', 'c3', 6);
INSERT INTO categories (id, webflow_item_id, name, tagline, short_description, color_key, sort_order) VALUES ('attention', '6a85786ec61c6c719566ef20', 'Attention', 'You''re the inventory. Stop supplying it.', 'Your attention, your posts and your data are the product these platforms sell. Withdraw the supply, block the ads, and fund the alternative with what you save.', 'c1', 7);